// Des: Time math for cron, once, pulse, solar triggers
// Flo: parse + validate at arm time (typo = reject, never silent) > match per tick on local wall clock (libc localtime, DST-safe) > fire verdict or next stamp
// I/O: schedule string + local time (armz, ticker) > bool fire-now, or next minute stamp (UI countdown)
// ===================================================================
const std = @import("std"); const base = @import("tk-time-base.zig"); const cron = @import("tk-time-cron.zig"); const sola = @import("tk-time-sola.zig"); const CF = base.CF;
pub const Local = base.Local; pub const localNow = base.localNow; pub const locaFrom = base.locaFrom; pub const daysFromCivil = base.daysFromCivil; pub const yearLeap = base.yearLeap; pub const montDays = base.montDays; pub const localFromMinuteStamp = base.localFromMinuteStamp; pub const civiDays = base.civiDays;
pub const CronFields = cron.CronFields; pub const CronError = cron.CronError; pub const parseCron = cron.parseCron; pub const cronMatch = cron.cronMatch; pub const nextCronMinute = cron.nextCronMinute;
pub const SolarEvent = sola.SolarEvent; pub const SolarSpec = sola.SolarSpec; pub const SolarError = sola.SolarError; pub const parseSolar = sola.parseSolar; pub const SunTimes = sola.SunTimes; pub const sunzTime = sola.sunzTime; pub const solarMinuteStamp = sola.solarMinuteStamp;
pub const PulseError = error{ BadNumber, TooSmall };
pub fn parsePulse(sche: []const u8) PulseError!u64 { const strn = std.mem.trim(u8, sche, CF.trim); if (strn.len == 0) return PulseError.BadNumber; var mult: u64 = 1; var body = strn; const last = strn[strn.len - 1]; if (last == 's' or last == 'S') { mult = 1000; body = strn[0 .. strn.len - 1]; } else if (last == 'm' or last == 'M') { mult = 60 * 1000; body = strn[0 .. strn.len - 1]; } else if (last == 'h' or last == 'H') { mult = 60 * 60 * 1000; body = strn[0 .. strn.len - 1]; } body = std.mem.trim(u8, body, CF.trim); if (body.len == 0) return PulseError.BadNumber; const numb = std.fmt.parseInt(u64, body, 10) catch return PulseError.BadNumber; const msec = std.math.mul(u64, numb, mult) catch return PulseError.BadNumber; if (msec < 1000) return PulseError.TooSmall; return msec - @mod(msec, 1000); }
pub const OnceError = error{ BadFormat, BadDate, BadTime };
pub fn parseOnce(sche: []const u8) OnceError!i64 { const strn = std.mem.trim(u8, sche, CF.trim); if (strn.len < 6) return OnceError.BadFormat; const date = strn[0..6]; for (date) |byte| if (byte < '0' or byte > '9') return OnceError.BadFormat; const yyzz = std.fmt.parseInt(u16, date[0..2], 10) catch return OnceError.BadFormat; const mmzz = std.fmt.parseInt(u8, date[2..4], 10) catch return OnceError.BadFormat; const ddzz = std.fmt.parseInt(u8, date[4..6], 10) catch return OnceError.BadFormat; const year: u16 = 2000 + yyzz; if (mmzz < 1 or mmzz > 12) return OnceError.BadDate; if (ddzz < 1 or ddzz > montDays(year, mmzz)) return OnceError.BadDate; var hour: u8 = 0; var minu: u8 = 0; if (strn.len > 6) { const sepa = strn[6]; if (sepa != '_' and sepa != '-') return OnceError.BadFormat; const clok = strn[7..]; if (clok.len != 2 and clok.len != 4 and clok.len != 6) return OnceError.BadFormat; for (clok) |byte| if (byte < '0' or byte > '9') return OnceError.BadFormat; hour = std.fmt.parseInt(u8, clok[0..2], 10) catch return OnceError.BadTime; if (clok.len >= 4) minu = std.fmt.parseInt(u8, clok[2..4], 10) catch return OnceError.BadTime; if (clok.len == 6) { const secz = std.fmt.parseInt(u8, clok[4..6], 10) catch return OnceError.BadTime; if (secz > 59) return OnceError.BadTime; } if (hour > 23) return OnceError.BadTime; if (minu > 59) return OnceError.BadTime; } return daysFromCivil(year, mmzz, ddzz) * 1440 + @as(i64, hour) * 60 + @as(i64, minu); }
pub const ONCE_LATE_WINDOW_MIN: i64 = 5;
pub fn onceDue(targ: i64, nowz: Local) bool { const delt = nowz.minute_stamp - targ; return delt >= 0 and delt <= ONCE_LATE_WINDOW_MIN; }
